import { useEffect, useState } from "react";
import { getJson } from "../api/client";


export function BlockedUsersPage() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [unlockingId, setUnlockingId] = useState(null);
  const [search, setSearch] = useState("");
  const [filteredUsers, setFilteredUsers] = useState([]);
  const [filter, setFilter] = useState("blocked"); // 'blocked', 'active', 'all'

  useEffect(() => {
    // On récupère tous les utilisateurs pour permettre tous les filtres
    getJson("/auth/all")
      .then((data) => {
        setUsers(data);
        // Par défaut, on filtre sur les bloqués
        setFilteredUsers(data.filter((u) => !u.isActive || (u.lockedUntil && new Date(u.lockedUntil) > new Date())));
      })
      .catch((e) => setError(e.message))
      .finally(() => setLoading(false));
  }, []);

  const handleUnlock = async (id) => {
    try {
      setUnlockingId(id);
      const res = await fetch(`/auth/unlock/id/${id}`, {
        method: "POST",
      });
      if (!res.ok) {
        throw new Error(`Erreur API ${res.status}`);
      }
      // On retire l'utilisateur débloqué de la liste locale
      setUsers((prev) => prev.filter((u) => u.id !== id));
      setFilteredUsers((prev) => prev.filter((u) => u.id !== id));
    } catch (e) {
      setError(e.message);
    } finally {
      setUnlockingId(null);
    }
  };



  const handleSearch = (e) => {
    e.preventDefault();
    applyFilters(filter, search);
  };

  const applyFilters = (filterType, searchValue) => {
    let filtered = users;
    if (filterType === "blocked") {
      filtered = filtered.filter((u) => !u.isActive || (u.lockedUntil && new Date(u.lockedUntil) > new Date()));
    } else if (filterType === "active") {
      filtered = filtered.filter((u) => u.isActive && (!u.lockedUntil || new Date(u.lockedUntil) <= new Date()));
    }
    if (searchValue) {
      filtered = filtered.filter((u) => u.email.toLowerCase().includes(searchValue.toLowerCase()));
    }
    setFilteredUsers(filtered);
  };

  const handleFilterChange = (e) => {
    const value = e.target.value;
    setFilter(value);
    applyFilters(value, search);
  };

  if (loading) return <p>Chargement...</p>;
  if (error) return <p>Erreur : {error}</p>;

  return (
    <div style={{ padding: "2rem", fontFamily: "sans-serif" }}>
      <h1>Utilisateurs</h1>
      <div style={{ marginBottom: "1rem" }}>
        <label htmlFor="filter-select" style={{ marginRight: "0.5rem" }}>Filtrer :</label>
        <select id="filter-select" value={filter} onChange={handleFilterChange} style={{ marginRight: "1rem", padding: "0.5rem" }}>
          <option value="blocked">Bloqués</option>
          <option value="active">Non-bloqués</option>
          <option value="all">Tous</option>
        </select>
        <form onSubmit={handleSearch} style={{ display: "inline" }}>
          <input
            type="text"
            placeholder="Recherche par email..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{ padding: "0.5rem", width: "250px" }}
          />
          <button type="submit" style={{ marginLeft: "0.5rem", padding: "0.5rem 1rem" }}>
            Rechercher
          </button>
        </form>
      </div>
      {filteredUsers.length === 0 ? (
        <p>Aucun utilisateur trouvé.</p>
      ) : (
        <table border="1" cellPadding="8">
          <thead>
            <tr>
              <th>Email</th>
              <th>Nom</th>
              <th>Tentatives échouées</th>
              <th>Bloqué jusqu&apos;au</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredUsers.map((u) => (
              <tr key={u.id}>
                <td>{u.email}</td>
                <td>{u.fullName}</td>
                <td>{u.failedLoginAttempts ?? 0}</td>
                <td>{u.lockedUntil}</td>
                <td>
                  {(!u.isActive || (u.lockedUntil && new Date(u.lockedUntil) > new Date())) && (
                    <button
                      onClick={() => handleUnlock(u.id)}
                      disabled={unlockingId === u.id}
                    >
                      {unlockingId === u.id ? "Déblocage..." : "Débloquer"}
                    </button>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
